// ============================================================================
// File: km_io_trigger_engine.sv
// Project: Kuzmin Machine (Машина Кузьміна) — PYNQ-Z1 Open-Source Overlay
// Module: km_io_trigger_engine
// Description:
//   EXP-06: Autonomous Physical & In-Silicon Reactive I/O Trigger Engine for "0p0".
//   Implements sub-30 ns event-driven subscription trigger in PL without CPU:
//
//     1. Edge Detection: Detects rising edge on physical pin (btn[0]/Pmod)
//        OR autonomous in-silicon stimulus pulse generated by hardware.
//     2. Concept Transition: Updates concept "0p0" state.
//     3. Subscription Action: Directly commutates output actuator pin (led[0]/Pmod)
//        within <= 3 clock cycles (<= 30.0 ns at 100 MHz).
//     4. Hardware Latency Profiler: Captures exact latency T_react = T_out - T_in
//        in clock cycles and nanoseconds, tracking min, max, last, and jitter.
// ============================================================================

`timescale 1ns / 1ps

module km_io_trigger_engine (
    input  wire        clk_i,
    input  wire        rst_ni,

    // Physical I/O pins
    input  wire        ext_pin_i,        // Physical input pin (BTN0 / Pmod JA[0])
    output reg         reactive_out_o,   // Physical output pin (LED0 / Pmod JB[0])

    // AXI Control & Command interface
    input  wire        start_stim_i,     // Pulse to start autonomous N-burst test
    input  wire        clear_stats_i,    // Clear min/max/count telemetry
    input  wire [15:0] burst_count_i,    // Number of autonomous triggers (default: 1000)

    // Status & Telemetry outputs
    output reg         busy_o,
    output reg         done_o,
    output reg         pass_o,           // Asserted if max_latency <= 3 cycles (30 ns)
    output reg  [15:0] last_latency_o,   // Latency of last event (cycles)
    output reg  [15:0] min_latency_o,    // Minimum latency observed (cycles)
    output reg  [15:0] max_latency_o,    // Maximum latency observed (cycles)
    output reg  [31:0] trigger_count_o,  // Total events triggered and handled
    output reg  [63:0] last_timestamp_o  // Free-running cycle timestamp of last event
);

    // Synchronizer for external physical pin (2-stage flip-flop)
    reg ext_sync_0_q, ext_sync_1_q, ext_prev_q;
    always @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            ext_sync_0_q <= 1'b0;
            ext_sync_1_q <= 1'b0;
            ext_prev_q   <= 1'b0;
        end else begin
            ext_sync_0_q <= ext_pin_i;
            ext_sync_1_q <= ext_sync_0_q;
            ext_prev_q   <= ext_sync_1_q;
        end
    end
    wire ext_rise = ext_sync_1_q && !ext_prev_q;

    // FSM for Autonomous Burst Stimulus
    localparam [1:0] S_IDLE    = 2'b00;
    localparam [1:0] S_STIM    = 2'b01;
    localparam [1:0] S_WAIT    = 2'b10;
    localparam [1:0] S_DONE    = 2'b11;

    reg [1:0] state_q;
    reg [15:0] target_burst_q;
    reg [15:0] stim_sent_cnt_q;
    reg [7:0]  stim_interval_cnt_q;
    reg [3:0]  drain_cnt_q;
    reg        stim_pulse_q;

    // Free-running 64-bit cycle counter for timestamping
    reg [63:0] cycle_cnt_q;
    always @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni)
            cycle_cnt_q <= 64'd0;
        else
            cycle_cnt_q <= cycle_cnt_q + 64'd1;
    end

    // Reactive Pipeline Stages
    // Stage 0: Event Arrival (Physical external or internal stimulus)
    reg        evt_detected_q;
    reg [63:0] evt_t0_q;

    // Stage 1: Concept "0p0" Evaluation & State Update
    reg        c0p0_val_q;
    reg        c0p0_valid_q;
    reg [63:0] c0p0_t0_q;

    // Stage 2: Subscriber Line Trigger & Actuator Output Drive
    reg        sub_trigger_q;
    reg [63:0] sub_t0_q;

    always @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            state_q             <= S_IDLE;
            busy_o              <= 1'b0;
            done_o              <= 1'b0;
            pass_o              <= 1'b0;
            last_latency_o      <= 16'd0;
            min_latency_o       <= 16'hFFFF;
            max_latency_o       <= 16'd0;
            trigger_count_o     <= 32'd0;
            last_timestamp_o    <= 64'd0;
            target_burst_q      <= 16'd0;
            stim_sent_cnt_q     <= 16'd0;
            stim_interval_cnt_q <= 8'd0;
            drain_cnt_q         <= 4'd0;
            stim_pulse_q        <= 1'b0;

            evt_detected_q      <= 1'b0;
            evt_t0_q            <= 64'd0;
            c0p0_val_q          <= 1'b0;
            c0p0_valid_q        <= 1'b0;
            c0p0_t0_q           <= 64'd0;
            sub_trigger_q       <= 1'b0;
            sub_t0_q            <= 64'd0;
            reactive_out_o      <= 1'b0;
        end else begin
            // Clear stats request
            if (clear_stats_i) begin
                min_latency_o   <= 16'hFFFF;
                max_latency_o   <= 16'd0;
                last_latency_o  <= 16'd0;
                trigger_count_o <= 32'd0;
                pass_o          <= 1'b0;
            end

            // Autonomous stimulus generator FSM
            case (state_q)
                S_IDLE: begin
                    busy_o       <= 1'b0;
                    stim_pulse_q <= 1'b0;
                    if (start_stim_i) begin
                        state_q             <= S_STIM;
                        busy_o              <= 1'b1;
                        done_o              <= 1'b0;
                        target_burst_q      <= (burst_count_i == 16'd0) ? 16'd1000 : burst_count_i;
                        stim_sent_cnt_q     <= 16'd0;
                        stim_interval_cnt_q <= 8'd0;
                        drain_cnt_q         <= 4'd0;
                    end
                end

                S_STIM: begin
                    // Emit 1-cycle stimulus pulse every 16 clock cycles
                    if (stim_interval_cnt_q == 8'd0) begin
                        stim_pulse_q        <= 1'b1;
                        stim_sent_cnt_q     <= stim_sent_cnt_q + 16'd1;
                        stim_interval_cnt_q <= 8'd15;
                        if (stim_sent_cnt_q + 16'd1 >= target_burst_q) begin
                            state_q <= S_WAIT;
                        end
                    end else begin
                        stim_pulse_q        <= 1'b0;
                        stim_interval_cnt_q <= stim_interval_cnt_q - 8'd1;
                    end
                end

                S_WAIT: begin
                    stim_pulse_q <= 1'b0;
                    drain_cnt_q  <= drain_cnt_q + 4'd1;
                    if (drain_cnt_q >= 4'd8) begin
                        state_q <= S_DONE;
                    end
                end

                S_DONE: begin
                    busy_o  <= 1'b0;
                    done_o  <= 1'b1;
                    pass_o  <= (max_latency_o <= 16'd3) && (trigger_count_o >= {16'd0, target_burst_q});
                    state_q <= S_IDLE;
                end

                default: state_q <= S_IDLE;
            endcase

            // ----------------------------------------------------------------
            // Reactive Pipeline
            // ----------------------------------------------------------------

            // Stage 0: Event Ingestion (Cycle 0: Stimulus pulse or External rise)
            if (stim_pulse_q || ext_rise) begin
                evt_detected_q <= 1'b1;
                evt_t0_q       <= cycle_cnt_q;
            end else begin
                evt_detected_q <= 1'b0;
            end

            // Stage 1: Concept "0p0" Evaluation (Cycle 1)
            c0p0_valid_q <= evt_detected_q;
            c0p0_t0_q    <= evt_t0_q;
            if (evt_detected_q) begin
                c0p0_val_q <= ~c0p0_val_q; // Toggle concept state
            end

            // Stage 2: Subscriber Line Trigger (Cycle 2)
            sub_trigger_q <= c0p0_valid_q;
            sub_t0_q      <= c0p0_t0_q;

            // Stage 3: Output Actuator Drive & Telemetry Capture (Cycle 3)
            if (sub_trigger_q) begin : blk_lat
                reg [15:0] latency_now;
                latency_now = cycle_cnt_q[15:0] - sub_t0_q[15:0];

                reactive_out_o   <= ~reactive_out_o; // Commutate physical output
                last_latency_o   <= latency_now;
                trigger_count_o  <= trigger_count_o + 32'd1;
                last_timestamp_o <= cycle_cnt_q;

                if (latency_now < min_latency_o)
                    min_latency_o <= latency_now;
                if (latency_now > max_latency_o)
                    max_latency_o <= latency_now;
            end
        end
    end

endmodule
